const indispos = $items().map(i => i.json);

return [{
  json: {
    indispos,
    count: indispos.length
  }
}];

const out = [];

for (const item of $items()) {
  const ev = item.json || {};
  if (String(ev.status || '').toLowerCase() === 'cancelled') continue;

  const start = ev.start?.dateTime || ev.start?.date || null;
  const end   = ev.end?.dateTime || ev.end?.date || null;
  const trainer = ev.organizer?.email || null;

  if (!trainer || !start || !end) continue;

  out.push({
    json: { trainer, start, end }
  });
}

return out;

const serie = $json.serie;
const candidates = $json.candidates || [];

const from = new Date(serie.from);
const to   = new Date(serie.to);

// liste des calendars Google (emails formateurs)
const calendarItems = candidates.map(c => ({
  id: c.email
}));

return [{
  json: {
    serie,
    candidates,

    // contexte général de planification
    context: {
      from: serie.from, // ISO string (Google attend du string)
      to: serie.to,
      nbParts: serie.nbParts,
      isFullDay: serie.isFullDay,
      strictDayPref: serie.strictDayPref,
      prefDays: serie.prefDays || [],
      prefHeure: serie.prefHeure || [],
      weekdayOverride: serie.weekdayOverride || [],
      otherPref: serie.otherPref || '',
      mode: serie.mode
    },

    // payload DIRECT pour Google Calendar FreeBusy
    googleCalendar: {
      timeMin: serie.from,
      timeMax: serie.to,
      items: calendarItems
    }
  }
}];

const serie = $json.serie;
const candidates = $json.candidates || [];
const context = $json.context;

const from = context.from; // ISO string
const to   = context.to;   // ISO string

return candidates.map(c => ({
  json: {
    // identite formateur
    trainer: {
      email: c.email,
      rank: c.rank,
      weeklyCap: c.weeklyCap,
      statut: c.statut
    },

    // contexte global (replique tel quel)
    context,

    // payload DIRECT pour Google Calendar
    googleCalendar: {
      calendarId: c.email,
      timeMin: from,
      timeMax: to,
      singleEvents: true,
      showDeleted: false,
      orderBy: 'startTime',
      maxResults: 250
    },

    // reference serie (utile pour la suite)
    serie: {
      recordId: serie.recordId,
      formation: serie.formation,
      nbParts: serie.nbParts,
      isFullDay: serie.isFullDay
    }
  }
}));
